import{_ as a,c as s,o,a0 as c}from"./chunks/framework.C1J0Vcxi.js";const h=JSON.parse('{"title":"第二十二周：从 embassy_preempt 重写为 rt-async —— 核心调度器与共享系统栈实现","description":"","frontmatter":{"title":"第二十二周：从 embassy_preempt 重写为 rt-async —— 核心调度器与共享系统栈实现","date":"2026-05-03"},"headers":[],"relativePath":"周报-Oveln/2026-05-03-周报二十二.md","filePath":"周报-Oveln/2026-05-03-周报二十二.md"}'),t={name:"周报-Oveln/2026-05-03-周报二十二.md"};function r(n,e,d,l,i,p){return o(),s("div",null,[...e[0]||(e[0]=[c(`<h1 id="第二十二周工作总结" tabindex="-1">第二十二周工作总结 <a class="header-anchor" href="#第二十二周工作总结" aria-label="Permalink to &quot;第二十二周工作总结&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本周启动了项目重写，将原 <strong>embassy_preempt</strong> 项目重命名为 <strong>rt-async</strong>，并从零重新设计了核心架构。新架构采用 <strong>共享系统栈 + 优先级抢占</strong> 模型，executor 切换复用 Rust 函数调用/返回语义，彻底消除了逐任务栈分配和传统上下文切换的开销。</p><p>从零完成了 executor 调度器的核心实现，包括优先级位图、任务状态机、Executor 运行循环、抢占式 Spawner，以及 RISC-V 裸机运行时。所有代码在 std 环境下通过基本验证。</p><h2 id="核心工作" tabindex="-1">核心工作 <a class="header-anchor" href="#核心工作" aria-label="Permalink to &quot;核心工作&quot;">​</a></h2><h3 id="_1-项目重启与优先级位图" tabindex="-1">1. 项目重启与优先级位图 <a class="header-anchor" href="#_1-项目重启与优先级位图" aria-label="Permalink to &quot;1. 项目重启与优先级位图&quot;">​</a></h3><p><strong>提交</strong>：<code>9698910</code> <code>fc8ad3e</code> — 2026-04-23</p><p>项目从 embassy_preempt 重写为 rt-async，设计目标：</p><ul><li><code>#![no_std]</code> 内核，纯 Rust 无 libc 依赖</li><li>共享系统栈，executor 不分配独立栈</li><li>任务数量无上限</li><li>O(1) 优先级调度</li></ul><p>首先实现了两级优先级位图 <code>PriorityBitmap&lt;G&gt;</code>（<code>modules/executor/src/priority_bitmap.rs</code>），支持 G ∈ [1, 64]，最多 4096 个优先级。<code>highest()</code> 通过两条 <code>trailing_zeros()</code> 指令单周期完成就绪查找。</p><h3 id="_2-executor-核心调度器" tabindex="-1">2. Executor 核心调度器 <a class="header-anchor" href="#_2-executor-核心调度器" aria-label="Permalink to &quot;2. Executor 核心调度器&quot;">​</a></h3><p><strong>提交</strong>：<code>2f3b293</code> <code>ef8df1d</code> <code>3edaeaf</code> <code>d90d04e</code> — 2026-04-29</p><p>分四个提交逐步构建了完整的调度器，架构详见技术文档「<a href="./../docs/scheduler.html">调度器设计</a>」和「<a href="./../docs/architecture.html">架构概览</a>」。</p><h4 id="基础类型层" tabindex="-1">基础类型层 <a class="header-anchor" href="#基础类型层" aria-label="Permalink to &quot;基础类型层&quot;">​</a></h4><p><code>modules/executor/src/</code> 下：</p><ul><li><code>priority.rs</code> — <code>Priority</code> newtype（封装 <code>usize</code>），反转序：数值越小优先级越高，<code>Ord</code> impl 翻转使 <code>&gt;</code> 表示更高优先级</li><li><code>util.rs</code> — <code>UninitCell&lt;T&gt;</code>（<code>MaybeUninit&lt;UnsafeCell&lt;T&gt;&gt;</code>），一次性写入的延迟初始化容器，用于 <code>TaskStorage</code> 中 Future 的静态存储</li></ul><h4 id="任务状态机与存储" tabindex="-1">任务状态机与存储 <a class="header-anchor" href="#任务状态机与存储" aria-label="Permalink to &quot;任务状态机与存储&quot;">​</a></h4><p><code>modules/executor/src/task/</code> 下：</p><ul><li><code>state.rs</code> — 任务状态原子变量，两个独立 bit flag：<code>STATE_SPAWNED</code>（已派发）和 <code>STATE_RUN_QUEUED</code>（在运行队列中）</li><li><code>storage.rs</code> — <code>TaskStorage&lt;F&gt;</code>，任务的静态存储单元，持有 Future + 状态 + 链表指针</li><li><code>header.rs</code> — <code>TaskInfo</code>（类型擦除的任务头）和 <code>TaskRef</code>（<code>NonNull&lt;TaskInfo&gt;</code> 封装），供 RunQueue 和 Waker 操作</li><li><code>run_queue.rs</code> — <code>RunQueue</code>，基于 <code>cordyceps::List</code> 的侵入式双向链表 FIFO 运行队列</li><li><code>waker.rs</code> — 基于 <code>TaskRef</code> 的 <code>RawWaker</code> / <code>RawWakerVTable</code> 实现，唤醒时调用 <code>wake_task</code> 将任务重新入队</li></ul><h4 id="executor-与-spawner" tabindex="-1">Executor 与 Spawner <a class="header-anchor" href="#executor-与-spawner" aria-label="Permalink to &quot;Executor 与 Spawner&quot;">​</a></h4><ul><li><code>executor.rs</code> — 单优先级 Executor，轮询 RunQueue 中的就绪 Future，通过 <code>BitmapOps</code> 回调与全局位图交互</li><li><code>spawner.rs</code> — <code>Spawner&lt;N&gt;</code> 全局调度器，核心设计： <ul><li><code>executors: [Executor; N]</code> — 每个优先级一个 Executor</li><li><code>prio_stack</code> — LIFO 优先级栈，记录当前占据系统栈空间的 executor（栈顶 = 当前运行）</li><li><code>try_preempt()</code> — 读取位图最高优先级与栈顶比较，更高则 push 并返回 RunToken</li><li><code>run()</code> / <code>complete_executor()</code> — 运行/弹出 executor</li></ul></li></ul><p>共享系统栈的核心原理详见技术文档「<a href="./../docs/shared-stack.html">共享系统栈</a>」：抢占 = 在被抢占 executor 栈帧之上调用新 executor 的 <code>run()</code>（嵌套函数调用），返回 = <code>run()</code> 返回后栈帧自然销毁。</p><h3 id="_3-std-环境适配" tabindex="-1">3. std 环境适配 <a class="header-anchor" href="#_3-std-环境适配" aria-label="Permalink to &quot;3. std 环境适配&quot;">​</a></h3><p><strong>提交</strong>：<code>66a410b</code> <code>af2aa76</code> — 2026-04-30</p><ul><li>将 <code>critical-section/std</code> 改为可选 feature，<code>no_std</code> 环境下使用平台实现</li><li>替换手动 <code>ceil_div</code> 为标准库 <code>div_ceil</code></li></ul><h3 id="_4-risc-v-裸机运行时与平台-crate" tabindex="-1">4. RISC-V 裸机运行时与平台 crate <a class="header-anchor" href="#_4-risc-v-裸机运行时与平台-crate" aria-label="Permalink to &quot;4. RISC-V 裸机运行时与平台 crate&quot;">​</a></h3><p><strong>提交</strong>：<code>6333bce</code> — 2026-05-01</p><p>新建 <code>modules/platform/</code> crate，包含 <code>riscv64-rt</code> 运行时：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>modules/platform/</span></span>
<span class="line"><span>├── archs/riscv64-rt/</span></span>
<span class="line"><span>│   ├── trap/         # Trap 入口汇编、TrapFrame 定义、trap_handler 分发</span></span>
<span class="line"><span>│   ├── handlers/     # Exception / Interrupt 默认处理</span></span>
<span class="line"><span>│   ├── start.rs      # _start → __rust_main 入口</span></span>
<span class="line"><span>│   └── panic.rs      # 裸机 panic handler</span></span>
<span class="line"><span>├── src/lib.rs        # 公共接口</span></span>
<span class="line"><span>└── src/logger.rs     # log 后端</span></span></code></pre></div><p>Trap 入口（<code>trap/entry.rs</code>）保存/恢复全部 callee-saved 寄存器，分发到 Rust <code>trap_handler</code>，是整个系统中唯一需要汇编的地方。</p><h2 id="模块结构" tabindex="-1">模块结构 <a class="header-anchor" href="#模块结构" aria-label="Permalink to &quot;模块结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rt-async/</span></span>
<span class="line"><span>├── modules/</span></span>
<span class="line"><span>│   ├── executor/          # 核心调度器</span></span>
<span class="line"><span>│   │   ├── spawner.rs     #   Spawner&lt;N&gt; 全局调度器</span></span>
<span class="line"><span>│   │   ├── executor.rs    #   Executor 单优先级执行器</span></span>
<span class="line"><span>│   │   ├── priority_bitmap.rs  # O(1) 两级位图</span></span>
<span class="line"><span>│   │   └── task/          #   TaskStorage、RunQueue、Waker</span></span>
<span class="line"><span>│   └── platform/          # RISC-V 运行时 + 平台抽象</span></span>
<span class="line"><span>└── apps/</span></span></code></pre></div>`,32)])])}const _=a(t,[["render",r]]);export{h as __pageData,_ as default};
